sys_script.script:
(function executeRule(current, previous) {

    try {

        if (current.subject.indexOf('Action Required: CLM Approval') == -1)
            return;

        var approvalGR = new GlideRecord('sysapproval_approver');

        if (!approvalGR.get(current.instance)) {
            gs.info('CLM: Approval not found');
            return;
        }

        var reqGR = new GlideRecord(approvalGR.source_table);

        if (!reqGR.get(approvalGR.document_id)) {
            gs.info('CLM: Request not found');
            return;
        }

        gs.info('CLM: Request Found = ' + reqGR.number);

        var copied = new GlideSysAttachment().copy(
            approvalGR.source_table,
            approvalGR.document_id.toString(),
            'sys_email',
            current.getUniqueValue()
        );

        gs.info('CLM: Copy Result = ' + copied);

    } catch (e) {

        gs.error('CLM Attachment Copy Error: ' + e);

    }

})(current, previous);
